  private ArrayList<JSONObject> completed(){ArrayList<JSONObject> list=new ArrayList<>();for(int i=0;i<tasks.length();i++){JSONObject o=tasks.optJSONObject(i);if(o!=null&&o.optBoolean("done"))list.add(o);}list.sort((a,b)->Long.compare(b.optLong("completed"),a.optLong("completed")));return list;}
  private ArrayList<JSONObject> filtered(){ArrayList<JSONObject> all=completed();if(mapFilter.equals("全部"))return all;Calendar c=Calendar.getInstance();long start=c.getTimeInMillis();if(mapFilter.equals("本週")){c.set(Calendar.DAY_OF_WEEK,c.getFirstDayOfWeek());c.set(Calendar.HOUR_OF_DAY,0);c.set(Calendar.MINUTE,0);start=c.getTimeInMillis();}else{c.set(Calendar.HOUR_OF_DAY,0);c.set(Calendar.MINUTE,0);start=c.getTimeInMillis();}ArrayList<JSONObject> out=new ArrayList<>();for(JSONObject o:all)if(o.optLong("completed")>=start)out.add(o);return out;}
  private void edit(JSONObject existing,boolean done){
    LinearLayout f=column();EditText title=new EditText(this),note=new EditText(this),category=new EditText(this),when=new EditText(this),start=new EditText(this),end=new EditText(this);
    title.setHint("目的地 / 任務名稱");note.setHint("票背留一句");category.setHint("分類（可留空）");when.setHint("日期 yyyy-MM-dd（可留空）");start.setHint("開始 HH:mm（可留空）");end.setHint("截止 HH:mm（可留空）");
    if(existing!=null){title.setText(existing.optString("title"));note.setText(existing.optString("note"));category.setText(existing.optString("category"));when.setText(existing.optString("date"));start.setText(existing.optString("start"));end.setText(existing.optString("end"));}
    for(EditText e:new EditText[]{title,note,category,when,start,end})f.addView(e);ScrollView sc=new ScrollView(this);sc.addView(f);
    AlertDialog d=new AlertDialog.Builder(this).setTitle("寫一張車票").setView(sc).setNegativeButton("取消",null).setPositiveButton("收好",null).create();d.setOnShowListener(x->d.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener(v->{try{String t=title.getText().toString().trim(),day=when.getText().toString().trim(),a=start.getText().toString().trim(),b=end.getText().toString().trim();if(t.isEmpty())throw new Exception("請寫低目的地");if(!day.isEmpty()){SimpleDateFormat fmt=new SimpleDateFormat("yyyy-MM-dd",Locale.US);fmt.setLenient(false);if(!day.matches("\\d{4}-\\d{2}-\\d{2}")||!fmt.format(fmt.parse(day)).equals(day))throw new Exception("日期格式錯誤");}for(String time:new String[]{a,b})if(!time.isEmpty()&&!time.matches("([01]\\d|2[0-3]):[0-5]\\d"))throw new Exception("時間格式應為 HH:mm");if(!a.isEmpty()&&!b.isEmpty()&&a.compareTo(b)>0)throw new Exception("截止時間不可早於開始時間");
      JSONObject o=existing==null?new JSONObject():new JSONObject(existing.toString());o.put("title",t).put("note",note.getText().toString()).put("category",category.getText().toString()).put("date",day).put("start",a).put("end",b);if(existing==null){o.put("id",UUID.randomUUID().toString()).put("done",done);if(done)o.put("completed",System.currentTimeMillis());tasks.put(o);}else for(int i=0;i<tasks.length();i++)if(tasks.optJSONObject(i)==existing)tasks.put(i,o);if(save()){d.dismiss();render();}
    }catch(Exception e){toast(e.getMessage()==null?"未能儲存":e.getMessage());}}));d.show();
  }
  private void card(JSONObject o,LinearLayout target){
    LinearLayout c=column();c.setPadding(dp(12),dp(6),dp(12),dp(6));GradientDrawable bg=new GradientDrawable();bg.setColor(0xfffffaeb);bg.setCornerRadius(dp(12));bg.setStroke(dp(1),0xffd8c6a8);c.setBackground(bg);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.setMargins(0,dp(8),0,dp(8));target.addView(c,lp);
    c.addView(text(o.optBoolean("done")?"票尾 · 已到站 "+date(o.optLong("completed")):"自由車票 · 長按拖曳驗票",13));c.addView(text(o.optString("title"),22));c.addView(text(o.optString("category")+"  "+o.optString("date")+"  "+o.optString("start")+" — "+o.optString("end"),12));if(!o.optString("note").isEmpty())c.addView(text(o.optString("note"),15));
    JSONArray list=photos(o);int shown=Math.min(list.length(),3);for(int i=0;i<shown;i++){ImageView im=new ImageView(this);Bitmap b=decode(list.optString(i),dp(140));if(b!=null){im.setImageBitmap(b);im.setContentDescription("相片 "+(i+1));im.setAdjustViewBounds(true);im.setMaxHeight(dp(140));c.addView(im);}}if(list.length()>3)c.addView(text("另有 "+(list.length()-3)+" 張相片，可在「管理相片」查看。",12));
    c.setOnLongClickListener(v->{if(o.optBoolean("done"))return false;ClipData data=ClipData.newPlainText("ticket",o.optString("id"));if(Build.VERSION.SDK_INT>=24)return v.startDragAndDrop(data,new View.DragShadowBuilder(v),o.optString("id"),0);return v.startDrag(data,new View.DragShadowBuilder(v),o.optString("id"),0);});
    c.addView(button(o.optBoolean("done")?"復原完成":"驗票 · 完成",()->{if(!o.optBoolean("done"))complete(o);else try{o.put("done",false);save();render();}catch(Exception e){toast("未能儲存");}}));c.addView(button("票背 / 更多",()->menu(o)));
  }
  private void complete(JSONObject o){if(busy||o.optBoolean("done"))return;try{o.put("done",true).put("completed",System.currentTimeMillis());cancel(o);if(!save())return;busy=true;LinearLayout f=column();f.setPadding(dp(24),dp(20),dp(24),dp(20));f.addView(text(o.optString("title"),24));TextView stamp=text("已驗票 · "+date(o.optLong("completed")),22);stamp.setTextColor(0xffa03832);stamp.setRotation(-10);stamp.setScaleX(2);stamp.setScaleY(2);stamp.setAlpha(0);f.addView(stamp);TextView tail=text("- - - - - - - - - - - - - -\n票尾 / "+o.optString("title"),18);f.addView(tail);AlertDialog d=new AlertDialog.Builder(this).setView(f).setPositiveButton("收好票尾",null).create();d.setOnDismissListener(v->{busy=false;render();});d.show();stamp.animate().alpha(1).scaleX(1).scaleY(1).setDuration(350).withEndAction(()->tail.animate().translationX(dp(100)).translationY(dp(30)).rotation(12).alpha(.2f).setDuration(650).start()).start();}catch(Exception e){busy=false;toast("驗票未能完成");}}
  private void wallet(){LinearLayout f=column();for(JSONObject o:completed())if(date(o.optLong("completed")).equals(date(System.currentTimeMillis())))card(o,f);if(f.getChildCount()==0)f.addView(text("今日未有票尾。未行完嘅路，下次再行。",18));ScrollView sc=new ScrollView(this);sc.addView(f);new AlertDialog.Builder(this).setTitle("今日票夾").setView(sc).setPositiveButton("收好今日",null).show();}
  private void menu(JSONObject o){new AlertDialog.Builder(this).setTitle(o.optString("title")).setItems(new String[]{"修改 / 留一句","開始呢一程","加相片（最多 6 張）","管理相片","提醒我","取消提醒","加入手機日曆","刪除車票"},(d,w)->{if(w==0)edit(o,false);if(w==1)new AlertDialog.Builder(this).setTitle(o.optString("title")).setMessage("慢慢行，唔需要倒數。").setPositiveButton("繼續旅程",null).show();if(w==2){if(photos(o).length()>=6){toast("每張車票最多 6 張相片");return;}photoTarget=o.optString("id");pick(REQUEST_PHOTO,Intent.ACTION_OPEN_DOCUMENT,"image/*");}if(w==3)managePhotos(o);if(w==4)remind(o);if(w==5){cancel(o);toast("已取消提醒");}if(w==6)try{startActivity(new Intent(Intent.ACTION_INSERT).setData(CalendarContract.Events.CONTENT_URI).putExtra(CalendarContract.Events.TITLE,o.optString("title")).putExtra(CalendarContract.Events.DESCRIPTION,o.optString("note")));}catch(Exception e){toast("未找到日曆 App");}if(w==7)new AlertDialog.Builder(this).setMessage("刪除車票？").setNegativeButton("取消",null).setPositiveButton("刪除",(a,b)->{cancel(o);for(int i=tasks.length()-1;i>=0;i--)if(tasks.optJSONObject(i)==o)tasks.remove(i);save();render();}).show();}).show();}
  private void managePhotos(JSONObject o){LinearLayout f=column();JSONArray list=photos(o);if(list.length()==0)f.addView(text("未有相片。",16));for(int i=0;i<list.length();i++){LinearLayout row=new LinearLayout(this);row.setOrientation(LinearLayout.HORIZONTAL);ImageView im=new ImageView(this);Bitmap b=decode(list.optString(i),dp(90));if(b!=null)im.setImageBitmap(b);im.setContentDescription("相片 "+(i+1));row.addView(im,new LinearLayout.LayoutParams(dp(90),dp(90)));int index=i;row.addView(button("刪除",()->{try{String p=list.optString(index);if(p.startsWith("file:")){File file=new File(Uri.parse(p).getPath());if(file.getAbsolutePath().startsWith(getFilesDir().getAbsolutePath()))file.delete();}list.remove(index);save();toast("已刪除相片");}catch(Exception e){toast("刪除失敗");}}));f.addView(row);}ScrollView sc=new ScrollView(this);sc.addView(f);new AlertDialog.Builder(this).setTitle("管理相片 · "+o.optString("title")).setView(sc).setPositiveButton("完成",null).show();}
  private Intent alarm(JSONObject o){return new Intent(this,ReminderReceiver.class).setData(Uri.parse("overlander://reminder/"+o.optString("id"))).putExtra("id",o.optString("id"));}
  private void cancel(JSONObject o){PendingIntent p=PendingIntent.getBroadcast(this,0,alarm(o),PendingIntent.FLAG_NO_CREATE|PendingIntent.FLAG_IMMUTABLE);if(p!=null){((AlarmManager)getSystemService(ALARM_SERVICE)).cancel(p);p.cancel();}((NotificationManager)getSystemService(NOTIFICATION_SERVICE)).cancel(o.optString("id").hashCode());}
  private void remind(JSONObject o){if(o.optBoolean("done")){toast("已完成車票唔需要提醒");return;}if(Build.VERSION.SDK_INT>=33&&checkSelfPermission("android.permission.POST_NOTIFICATIONS")!=PackageManager.PERMISSION_GRANTED){requestPermissions(new String[]{"android.permission.POST_NOTIFICATIONS"},REQUEST_NOTIFICATIONS);toast("授權後請重新選擇提醒");return;}new AlertDialog.Builder(this).setTitle("約略提醒（重啟後需重設）").setItems(new String[]{"15 分鐘後","1 小時後","明日呢個時間"},(d,w)->{try{PendingIntent p=PendingIntent.getBroadcast(this,0,alarm(o),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);((AlarmManager)getSystemService(ALARM_SERVICE)).setAndAllowWhileIdle(AlarmManager.RTC_WAKEUP,System.currentTimeMillis()+new long[]{900000,3600000,86400000}[w],p);toast("已安排約略提醒");}catch(Exception e){toast("提醒未能安排");}}).show();}
  private void calendar(){if(checkSelfPermission("android.permission.READ_CALENDAR")!=PackageManager.PERMISSION_GRANTED){requestPermissions(new String[]{"android.permission.READ_CALENDAR"},REQUEST_CALENDAR);return;}io.execute(()->{ArrayList<String> labels=new ArrayList<>(),ids=new ArrayList<>();try(Cursor c=getContentResolver().query(CalendarContract.Calendars.CONTENT_URI,new String[]{"_id","calendar_displayName"},null,null,null)){if(c!=null)while(c.moveToNext()){ids.add(c.getString(0));labels.add(c.getString(1));}runOnUiThread(()->new AlertDialog.Builder(this).setTitle("選擇日曆（未來 30 日）").setItems(labels.toArray(new String[0]),(d,w)->events(ids.get(w))).setNegativeButton("取消",null).show());}catch(Exception e){runOnUiThread(()->toast("日曆未能讀取 / 權限被拒絕"));}});}
  @Override public void onRequestPermissionsResult(int r,String[] p,int[] g){super.onRequestPermissionsResult(r,p,g);if(r==REQUEST_CALENDAR){if(g.length>0&&g[0]==PackageManager.PERMISSION_GRANTED)calendar();else toast("未授權日曆，其他功能仍可使用");}}
  private String range(long begin,long end,String zone,boolean allDay){String b=date(begin),e=date(end);if(allDay)return b+" 全日";if(b.equals(e))return b+" "+clock(begin,zone)+" — "+clock(end,zone);return b+" "+clock(begin,zone)+" — "+e+" "+clock(end,zone)+"（跨夜）";}
  private void events(String id){io.execute(()->{ArrayList<JSONObject> rows=new ArrayList<>();ArrayList<String> labels=new ArrayList<>();try{long now=System.currentTimeMillis();Uri.Builder u=CalendarContract.Instances.CONTENT_URI.buildUpon();ContentUris.appendId(u,now);ContentUris.appendId(u,now+30L*86400000);try(Cursor c=getContentResolver().query(u.build(),new String[]{"event_id","title","begin","end","eventTimezone","allDay","location","description","rrule"},"calendar_id=?",new String[]{id},"begin ASC")){if(c!=null)while(c.moveToNext()){boolean allDay=c.getInt(5)!=0;String zone=c.getString(4);long begin=c.getLong(2),end=c.getLong(3);JSONObject o=new JSONObject().put("calendarKey",id+":"+c.getLong(0)+":"+begin).put("title",c.isNull(1)?"未命名行程":c.getString(1)).put("date",date(begin)).put("start",allDay?"":clock(begin,zone)).put("end",allDay?"":clock(end,zone)).put("endDate",date(end)).put("allDay",allDay).put("timezone",zone).put("location",c.getString(6)).put("description",c.getString(7)).put("recurrence",c.getString(8));rows.add(o);labels.add(range(begin,end,zone,allDay)+" · "+o.optString("title")+(TextUtils.isEmpty(o.optString("location"))?"":" · "+o.optString("location"))+(TextUtils.isEmpty(o.optString("recurrence"))?"":" · 重複"));}}runOnUiThread(()->{boolean[] chosen=new boolean[rows.size()];new AlertDialog.Builder(this).setTitle("選擇匯入（本機副本，非同步）").setMultiChoiceItems(labels.toArray(new String[0]),chosen,(d,w,b)->chosen[w]=b).setNegativeButton("取消",null).setPositiveButton("匯入",(d,w)->{try{int n=0;for(int i=0;i<rows.size();i++)if(chosen[i]){JSONObject o=rows.get(i);boolean duplicate=false;for(int j=0;j<tasks.length();j++)if(o.optString("calendarKey").equals(tasks.optJSONObject(j).optString("calendarKey")))duplicate=true;if(!duplicate){o.put("id",UUID.randomUUID().toString()).put("done",false).put("category","日曆");tasks.put(o);n++;}}if(save())toast("已匯入 "+n+" 項");render();}catch(Exception e){toast("匯入失敗");}}).show();});}catch(Exception e){runOnUiThread(()->toast("行程讀取失敗"));}});}
  private void sounds(){
    body.addView(text("窗邊收音機 · 播放清單 / 進度 / 循環",21));
    int loopMode=prefs.getInt("loopMode",1);
    JSONArray playlist=new JSONArray();
    try{playlist=new JSONArray(prefs.getString("playlist","[]"));}catch(Exception e){}
    int index=prefs.getInt("playlistIndex",0);
    body.addView(text("播放清單："+(playlist.length()==0?"未加入":(Math.min(index+1,playlist.length()))+" / "+playlist.length()+" 首"),15));
    body.addView(button("加入音樂（可多選，最多 20 首）",()->pick(REQUEST_MUSIC,Intent.ACTION_OPEN_DOCUMENT,"audio/*")));
    LinearLayout controls=new LinearLayout(this);controls.addView(button("上一首",()->media("prev",null,-1)),new LinearLayout.LayoutParams(0,-2,1));controls.addView(button("播放 / 暫停",()->media("toggle",null,-1)),new LinearLayout.LayoutParams(0,-2,1));controls.addView(button("下一首",()->media("next",null,-1)),new LinearLayout.LayoutParams(0,-2,1));body.addView(controls);
    progressBar=new SeekBar(this);progressBar.setMax(1000);progressBar.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener(){public void onProgressChanged(SeekBar s,int p,boolean user){}public void onStartTrackingTouch(SeekBar s){}public void onStopTrackingTouch(SeekBar s){media("seek",null,progressBar.getProgress());}});body.addView(progressBar);
    body.addView(button("循環模式："+(loopMode==0?"關閉":loopMode==1?"全部循環":"單曲循環"),()->{int next=(prefs.getInt("loopMode",1)+1)%3;prefs.edit().putInt("loopMode",next).commit();media("loop",null,-1);render();}));
    body.addView(button("停止播放",()->media("stop",null,-1)));body.addView(button("播放原創合成火車聲",this::generateRail));
    for(String s:new String[]{"晨光","黃昏","夜行"})body.addView(button(s+"窗景",()->{scene=s;prefs.edit().putString("scene",s).apply();render();}));
    body.addView(text("音樂選擇會保留；相片 / 音樂卸載後會移除，請先備份。JSON 備份包含相片，不含音樂。",13));
  }
  private void media(String action,String path,int position){try{Intent i=new Intent(this,MusicPlaybackService.class).setAction(action);if(path!=null)i.putExtra("path",path);if(position>=0)i.putExtra("position",position);if("stop".equals(action)){stopService(i);return;}if(Build.VERSION.SDK_INT>=26)startForegroundService(i);else startService(i);}catch(Exception e){toast("背景播放未能啟動");}}
  private void generateRail(){io.execute(()->{try{File f=new File(getFilesDir(),"rail.wav");int rate=22050,n=rate*6;try(DataOutputStream out=new DataOutputStream(new FileOutputStream(f))){out.writeBytes("RIFF");le(out,36+n*2,4);out.writeBytes("WAVEfmt ");le(out,16,4);le(out,1,2);le(out,1,2);le(out,rate,4);le(out,rate*2,4);le(out,2,2);le(out,16,2);out.writeBytes("data");le(out,n*2,4);Random random=new Random(41);for(int i=0;i<n;i++){double t=i/(double)rate,q=t%.75,env=Math.exp(-q*34)+(q>.16?.65*Math.exp(-(q-.16)*34):0);int value=(int)((.18*env*Math.sin(2*Math.PI*92*t)+.025*(random.nextDouble()*2-1))*20000);le(out,value,2);}}runOnUiThread(()->media("playRail",f.getAbsolutePath(),-1));}catch(Exception e){runOnUiThread(()->toast("火車聲未能建立"));}});}
  private void le(DataOutputStream o,int v,int n)throws IOException{for(int i=0;i<n;i++)o.writeByte(v>>>(8*i));}
  private void pick(int code,String action,String type){try{Intent i=new Intent(action).setType(type).addCategory(Intent.CATEGORY_OPENABLE);if(code==REQUEST_EXPORT)i.putExtra(Intent.EXTRA_TITLE,"overlander-"+date(System.currentTimeMillis())+".json");if(code==REQUEST_PHOTO||code==REQUEST_MUSIC)i.putExtra(Intent.EXTRA_ALLOW_MULTIPLE,true);startActivityForResult(i,code);}catch(Exception e){toast("未找到檔案選擇工具");}}
  private byte[] read(Uri u,int max)throws Exception{try(InputStream in=getContentResolver().openInputStream(u);ByteArrayOutputStream out=new ByteArrayOutputStream()){if(in==null)throw new IOException();byte[] b=new byte[8192];int n;while((n=in.read(b))!=-1){if(out.size()+n>max)throw new IOException("檔案過大");out.write(b,0,n);}return out.toByteArray();}}
  private File compress(Uri u)throws Exception{BitmapFactory.Options bounds=new BitmapFactory.Options();bounds.inJustDecodeBounds=true;try(InputStream in=getContentResolver().openInputStream(u)){if(in==null)throw new IOException();BitmapFactory.decodeStream(in,null,bounds);}int sample=1;while(bounds.outWidth/(sample*2)>=1600||bounds.outHeight/(sample*2)>=1600)sample*=2;BitmapFactory.Options opts=new BitmapFactory.Options();opts.inSampleSize=sample;Bitmap source;try(InputStream in=getContentResolver().openInputStream(u)){if(in==null)throw new IOException();source=BitmapFactory.decodeStream(in,null,opts);}if(source==null)throw new IOException("無法解碼相片");int w=source.getWidth(),h=source.getHeight();if(w>1600||h>1600){float scale=Math.min(1600f/w,1600f/h);source=Bitmap.createScaledBitmap(source,Math.max(1,(int)(w*scale)),Math.max(1,(int)(h*scale)),true);}File dir=new File(getFilesDir(),"photos");if(!dir.exists()&&!dir.mkdirs())throw new IOException();File file=new File(dir,UUID.randomUUID().toString()+".jpg");try(FileOutputStream out=new FileOutputStream(file)){if(!source.compress(Bitmap.CompressFormat.JPEG,82,out))throw new IOException();}return file;}
  private Bitmap decode(String path,int target){try{BitmapFactory.Options o=new BitmapFactory.Options();o.inJustDecodeBounds=true;try(InputStream in=getContentResolver().openInputStream(Uri.parse(path))){if(in==null)return null;BitmapFactory.decodeStream(in,null,o);}int sample=1;while(o.outWidth/(sample*2)>=target||o.outHeight/(sample*2)>=target)sample*=2;BitmapFactory.Options d=new BitmapFactory.Options();d.inSampleSize=sample;try(InputStream in=getContentResolver().openInputStream(Uri.parse(path))){if(in==null)return null;return BitmapFactory.decodeStream(in,null,d);}}catch(Exception e){return null;}}
  @Override protected void onActivityResult(int r,int result,Intent data){super.onActivityResult(r,result,data);if(result!=RESULT_OK||data==null)return;Uri single=data.getData();ArrayList<Uri> uris=new ArrayList<>();if((r==REQUEST_PHOTO||r==REQUEST_MUSIC)&&data.getClipData()!=null){for(int i=0;i<data.getClipData().getItemCount();i++)uris.add(data.getClipData().getItemAt(i).getUri());}else if(single!=null)uris.add(single);if(uris.isEmpty())return;final String target=photoTarget;final String snapshot=tasks.toString();io.execute(()->{try{if(r==REQUEST_PHOTO){JSONObject o=find(target);if(o==null){toast("車票已不存在");return;}JSONArray list=photos(o);int added=0;for(Uri u:uris){if(list.length()>=6)break;File f=compress(u);list.put(Uri.fromFile(f).toString());added++;}final int count=added;runOnUiThread(()->{if(save()){toast("已加入 "+count+" 張相片");render();}});}else if(r==REQUEST_MUSIC){JSONArray playlistArray=new JSONArray();try{playlistArray=new JSONArray(prefs.getString("playlist","[]"));}catch(Exception e){}final JSONArray playlist=playlistArray;int added=0;for(Uri u:uris){if(playlist.length()>=20)break;byte[] bytes=read(u,64*1024*1024);File dir=new File(getFilesDir(),"audio");if(!dir.exists()&&!dir.mkdirs())throw new IOException();File file=new File(dir,UUID.randomUUID().toString());try(FileOutputStream out=new FileOutputStream(file)){out.write(bytes);}playlist.put(file.getAbsolutePath());added++;}final int count=added;prefs.edit().putString("playlist",playlist.toString()).commit();runOnUiThread(()->{toast("已加入 "+count+" 首音樂");media("reload",null,-1);render();});}else if(r==REQUEST_EXPORT){JSONObject backup=new JSONObject().put("format","overlander").put("version",3).put("createdAt",System.currentTimeMillis());JSONArray list=new JSONArray(snapshot);int imageCount=0;for(int i=0;i<list.length();i++){JSONObject o=list.getJSONObject(i);JSONArray source=photos(o);JSONArray images=new JSONArray();for(int j=0;j<source.length();j++){images.put(android.util.Base64.encodeToString(read(Uri.parse(source.optString(j)),4*1024*1024),android.util.Base64.NO_WRAP));imageCount++;}o.remove("photo");o.remove("photos");o.put("photosBase64",images);}backup.put("taskCount",list.length()).put("photoCount",imageCount).put("tasks",list);byte[] bytes=backup.toString().getBytes(java.nio.charset.StandardCharsets.UTF_8);if(bytes.length>32*1024*1024)throw new IOException("備份超過 32 MB");try(OutputStream out=getContentResolver().openOutputStream(uris.get(0),"wt")){if(out==null)throw new IOException();out.write(bytes);}final int exportedTaskCount = list.length(); final int exportedPhotoCount = imageCount;  runOnUiThread(() ->     toast("已匯出 " + exportedTaskCount         + " 張車票、" + exportedPhotoCount + " 張相片") );}else if(r==REQUEST_IMPORT){JSONObject root=new JSONObject(new String(read(uris.get(0),32*1024*1024),java.nio.charset.StandardCharsets.UTF_8));int version=root.optInt("version");if(!"overlander".equals(root.optString("format"))||(version!=2&&version!=3))throw new IOException("不支援嘅備份格式");JSONArray list=root.getJSONArray("tasks");HashSet<String> ids=new HashSet<>();if(list.length()>10000)throw new IOException("紀錄過多");int imageCount=0;for(int i=0;i<list.length();i++){JSONObject o=list.getJSONObject(i);String id=o.getString("id");if(id.isEmpty()||!ids.add(id)||o.getString("title").trim().isEmpty()||!(o.get("done") instanceof Boolean))throw new IOException("車票資料格式錯誤");JSONArray images=new JSONArray();if(version==3)images=o.optJSONArray("photosBase64")==null?new JSONArray():o.optJSONArray("photosBase64");else if(!o.optString("photoBase64").isEmpty())images.put(o.optString("photoBase64"));o.remove("photo");o.remove("photos");o.remove("photoBase64");o.remove("photosBase64");JSONArray files=new JSONArray();for(int j=0;j<images.length();j++){byte[] image=android.util.Base64.decode(images.getString(j),android.util.Base64.DEFAULT);if(image.length>4*1024*1024)throw new IOException("相片過大");File dir=new File(getFilesDir(),"photos");dir.mkdirs();File f=new File(dir,UUID.randomUUID().toString()+".jpg");try(FileOutputStream out=new FileOutputStream(f)){out.write(image);}files.put(Uri.fromFile(f).toString());imageCount++;}o.put("photos",files);}final int taskCount=list.length(),photoCount=imageCount;runOnUiThread(()->new AlertDialog.Builder(this).setTitle("還原前預覽").setMessage("備份版本："+version+"\n將還原 "+taskCount+" 張車票、"+photoCount+" 張相片。\n\n會取代現有車票；原資料另存於本機 recovery_tasks。現有提醒會取消。取消則不更改車票。").setNegativeButton("取消",null).setPositiveButton("取代並還原",(d,w)->{String old=prefs.getString("tasks","[]");if(prefs.edit().putString("recovery_tasks",old).putString("tasks",list.toString()).commit()){for(int i=0;i<tasks.length();i++)cancel(tasks.optJSONObject(i));tasks=list;healthy=true;migrate();render();toast("已還原");}else toast("還原儲存失敗");}).show());}}catch(Exception e){runOnUiThread(()->toast("操作未完成："+(e.getMessage()==null?"無法讀寫檔案":e.getMessage())));}});}
  private class WindowView extends View {Paint p=new Paint(3);WindowView(){super(MainActivity.this);}protected void onDraw(Canvas c){float w=getWidth(),h=getHeight();boolean night=scene.equals("夜行");c.drawColor(night?0xff182b45:scene.equals("晨光")?0xffc3e0dc:0xffe9ba85);p.setColor(0xffffedb7);c.drawCircle(w*.8f,h*.25f,dp(15),p);float offset=(SystemClock.uptimeMillis()/35f)%dp(160);for(int i=-1;i<6;i++){float x=i*dp(160)-offset;Path hill=new Path();hill.moveTo(x,h);hill.lineTo(x+dp(80),h*.35f);hill.lineTo(x+dp(170),h);hill.close();p.setColor(night?0xff263d42:0xff64836b);c.drawPath(hill,p);}p.setColor(green);c.drawRect(0,h*.85f,w,h,p);p.setColor(cream);p.setTextSize(dp(13));c.drawText(scene+"慢車 / THE OVERLANDER",dp(12),h-dp(9),p);if(isShown()&&getWindowVisibility()==VISIBLE)postInvalidateDelayed(40);}}
  private class MapView extends View {Paint p=new Paint(3);ScaleGestureDetector scale;ArrayList<JSONObject> stops=filtered();ArrayList<RectF> hitAreas=new ArrayList<>();ArrayList<JSONObject> hitStops=new ArrayList<>();MapView(){super(MainActivity.this);scale=new ScaleGestureDetector(MainActivity.this,new ScaleGestureDetector.SimpleOnScaleGestureListener(){public boolean onScale(ScaleGestureDetector d){mapZoom=Math.max(.5f,Math.min(3f,mapZoom*d.getScaleFactor()));invalidate();return true;}});setContentDescription("旅程地圖；以下按鈕可回顧全部旅程");}protected void onDraw(Canvas c){hitAreas.clear();hitStops.clear();int total=stops.size();int pages=(total+19)/20;if(mapPage>=pages)mapPage=Math.max(0,pages-1);int from=mapPage*20,to=Math.min(total,from+20);float cx=getWidth()/2f,cy=getHeight()/2f;c.save();c.translate(cx,cy);c.scale(mapZoom,mapZoom);c.translate(-cx,-cy);p.setColor(green);p.setStrokeWidth(dp(3));for(int i=from;i<to;i++){int local=i-from;float x=dp(28)+(local%4)*(getWidth()-dp(56))/3f,y=dp(26)+(local/4)*dp(47);if(local>0){int j=local-1;float px=dp(28)+(j%4)*(getWidth()-dp(56))/3f,py=dp(26)+(j/4)*dp(47);c.drawLine(px,py,x,y,p);}c.drawCircle(x,y,dp(7),p);p.setTextSize(dp(11));c.drawText("站"+(i+1),x-dp(12),y+dp(20),p);float sx=cx+(x-cx)*mapZoom,sy=cy+(y-cy)*mapZoom;hitAreas.add(new RectF(sx-dp(24),sy-dp(24),sx+dp(24),sy+dp(24)));hitStops.add(stops.get(i));}if(total==0){p.setTextSize(dp(16));c.drawText("這個範圍未有完成旅程。",dp(20),dp(80),p);}c.restore();}public boolean onTouchEvent(android.view.MotionEvent e){scale.onTouchEvent(e);if(e.getAction()==android.view.MotionEvent.ACTION_UP){for(int i=0;i<hitAreas.size();i++){if(hitAreas.get(i).contains(e.getX(),e.getY())){performClick();review(hitStops.get(i));return true;}}}return true;}public boolean performClick(){super.performClick();return true;}}
  private void review(JSONObject o){new AlertDialog.Builder(this).setTitle(o.optString("title")).setMessage(date(o.optLong("completed"))+"\n"+o.optString("note")).setPositiveButton("收好回憶",null).show();}
